# %% 03.01_TwoArmedBandit.ipynb 5
class TwoArmedBandit(ebase):
    """
    Distributional Two-Armed Bandit Environment with a single state.
    """ 

    def __init__(self,
                 disttype="continuous", # continuous or discrete
                 distA=None, # reward distribution for option A
                 distB=None,  # reward distribution for option B
                 xs=None,
                 ps=None):  
            
        self.N = 1
        self.M = 2
        self.Z = 1

        self.disttype = disttype
        self.dist = [distA, distB]
        self.xs = xs
        self.ps = ps
        
        self.Aset = self.actions()  # to have them available for the creation
        self.Sset = self.states()   # of the Transition and Reward Tensors

        self.state = 1 # initial state
        
        self.T = self.TransitionTensor()
        self.R = self.RewardTensor()
        self.Rdict = self.RewardDict()
        self.F = np.array(self.FinalStates())
        # super().__init__()

