# %% 03.01_TwoArmedBandit.ipynb 8
@patch
def TransitionTensor(self:TwoArmedBandit):
    """Get the Transition Tensor."""
    dim = np.concatenate(([self.Z],
                          [self.M],
                          [self.Z]))
    Tsas = np.ones(dim) * (-1)

    for index, _ in np.ndenumerate(Tsas):
        Tsas[index] = 1.
    return Tsas

# %% 03.01_TwoArmedBandit.ipynb 9
@patch
def RewardTensor(self:TwoArmedBandit):
    """Get the Reward Tensor R[i,s,a1,...,aN,s']."""
    dim = np.concatenate(([self.N],
                          [self.Z],
                          [self.M],
                          [self.Z]))
    Risas = np.zeros(dim)

    for index, _ in np.ndenumerate(Risas):
        Risas[index] = self._reward(index[0], index[1], index[2],
                                    index[3])
    return Risas

@patch
def _reward(self:TwoArmedBandit,
            i:int, # the agent index
            s:int, # the state index
            a:int, # indices for joint actions
            s_:int  # the next-state index
            ) -> float:  # reward value
    """
    Returns the reward value for agent `i` in current state `s`, under joint action `jA`, when transitioning to next state `s_`.
    """
    if self.Aset[0][a] == 'A':  # if action was A
        if self.disttype == 'continuous':
            return self.dist[0][1]  # the agents receive mean reward
        else:  # discrete
            return np.dot(self.xs[0, :], self.ps[0, :])
    
    else:  # if action was B
        if self.disttype == 'continuous':
            return self.dist[1][1]  # the agents receive mean reward
        else:  # discrete
            return np.dot(self.xs[1, :], self.ps[1, :])

# %% 03.01_TwoArmedBandit.ipynb 10
@patch
def RewardDict(self:TwoArmedBandit):
    """Get the Reward Dict."""
    
    if self.disttype == 'continuous':
        dim = np.concatenate(([self.N],
                              [self.Z],
                              [self.M],
                              [self.Z]))
        loc = np.zeros((dim))  # mean reward
        scale = np.zeros((dim))  # sd
        distr = np.empty((dim), dtype=object)  # distribution type
    
        loc[:, :, 0, :] = self.dist[0][1]  # mean R after choosing option A
        loc[:, :, 1, :] = self.dist[1][1]  # mean R after choosing option B
        scale[:, :, 0, :] = self.dist[0][2]
        scale[:, :, 1, :] = self.dist[1][2]
        distr[:, :, 0, :] = self.dist[0][0]
        distr[:, :, 1, :] = self.dist[1][0]
    
        # Create dict with previous arrays
        d = dict.fromkeys(["dist", "loc", "scale"])
        d['dist'] = distr
        d['loc'] = loc
        d['scale'] = scale
    
    else:  # discrete
        dim = np.concatenate(([self.N],
                              [self.Z],
                              [self.M],
                              [self.Z],
                              [len(self.xs[0, :])]))
        x = np.zeros((dim))
        p = np.zeros((dim))
        x[:, :, 0, :, :] = self.xs[0, :]  
        x[:, :, 1, :, :] = self.xs[1, :]  
        p[:, :, 0, :, :] = self.ps[0, :]  
        p[:, :, 1, :, :] = self.ps[1, :] 
        
        # Create dict with previous arrays
        d = dict.fromkeys(["x", "p"])
        d['x'] = x
        d['p'] = p
        
    return d

