@patch
def id(self:TwoArmedBandit):
    """
    Returns id string of environment
    """
    # Default
    if self.disttype == 'continuous':
        dA = self.dist[0][0]
        dB = self.dist[1][0]
        muA = self.dist[0][1]
        muB = self.dist[1][1]
        id = f"{self.__class__.__name__}_"+\
        f"{dA}_{str(muA)}_{dB}_{str(muB)}"
        
    else:  # discrete
        rew = self.xs[0, 1]
        pun = self.xs[0, 0]
        pA = self.ps[0, 1]
        pB = self.ps[1, 1]
        id = f"{self.__class__.__name__}_"+\
        f"{str(rew)}_{str(pun)}_{str(pA)}_{str(pB)}"
        
    return id

